package com.lexorion.workforce.domain;
import com.lexorion.workforce.config.Auditable;import jakarta.persistence.*;import java.util.UUID;import lombok.*;import org.hibernate.annotations.UuidGenerator;
@Entity @Table(name="departments",uniqueConstraints=@UniqueConstraint(name="uk_department_workspace_key",columnNames={"workspace_id","department_key"}),indexes={@Index(name="idx_department_workspace",columnList="workspace_id"),@Index(name="idx_department_status",columnList="status")}) @Getter @Setter @NoArgsConstructor
public class Department extends Auditable {@Id @UuidGenerator private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="workspace_id",nullable=false,updatable=false)private WorkforceWorkspace workspace;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="parent_department_id")private Department parent;@Column(name="department_key",nullable=false,length=63,updatable=false)private String key;@Column(nullable=false,length=150)private String name;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private ActiveStatus status=ActiveStatus.ACTIVE;}
